def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'

    last_my, last_opp = history[-1]

    # Count recent opponent behavior over several horizons
    opp_def_total = 0
    opp_c_total = 0
    for _, o in history:
        if o == 'D':
            opp_def_total += 1
        else:
            opp_c_total += 1

    window = history[-12:]
    w = len(window)
    opp_def_recent = 0
    streak_d = 0
    for _, o in window:
        if o == 'D':
            opp_def_recent += 1
    for _, o in reversed(history):
        if o == 'D':
            streak_d += 1
        else:
            break

    my_def_total = 0
    for m, _ in history:
        if m == 'D':
            my_def_total += 1

    opp_coop_rate = opp_c_total / n

    # Always-defect opponent: stop feeding them
    if opp_def_total == n and n >= 4:
        return 'D'

    # Never-defect opponent: preserve mutual cooperation, exploit only late
    if opp_def_total == 0:
        if n >= 97:
            return 'D'
        return 'C'

    # Opponent just defected: short punishment, then reconcile
    if last_opp == 'D':
        # If opponent rarely defects overall, forgive quickly with cooperation
        if opp_coop_rate >= 0.8:
            if streak_d >= 3:
                return 'D'
            return 'C'
        # Moderate opponent: punish current streak up to 2, then return to C
        if streak_d == 1:
            return 'D'
        if streak_d == 2:
            return 'D'
        # Long streak: keep defecting but probe occasionally
        if opp_coop_rate >= 0.4:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # Repair: if we were defecting, return to cooperation now.
    if last_my == 'D':
        return 'C'

    # Both cooperated last round.
    # If opponent has been mostly cooperative, keep cooperating.
    if opp_def_recent <= 2 and opp_coop_rate >= 0.6:
        # Very mild late exploit against pure cooperators
        if opp_def_total <= 1 and n >= 95:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Opponent mixed with notable recent defection but just cooperated.
    # Cooperate to encourage recovery, but punish if they defected a lot.
    if opp_def_recent >= 6:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    if opp_def_recent >= 4:
        if my_def_total > opp_def_total + 2:
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    if my_def_total > opp_def_total + 3:
        return 'C'

    return 'C'
